"""Installed-layout fixture for RepoInvariant's experimental scanner API."""

import hashlib

from repoinvariant.models import Severity
from repoinvariant.plugin_api import PluginFinding, PluginLocation, PluginRule


class SampleScanner:
    api_version = 1
    plugin_id = "sample.todo"
    rules = (
        PluginRule(
            code="TODO001",
            default_severity=Severity.WARNING,
            description="A configured fixture marker is present.",
        ),
    )

    def scan(self, repository, config):
        patterns = config.get("patterns", ("**/*.todo",))
        marker = config.get("marker", "TODO")
        findings = []
        for path in repository.files(patterns):
            for line_number, line in enumerate(repository.read_text(path).splitlines(), start=1):
                if line.strip() == marker:
                    entity = hashlib.sha256(
                        f"{path}\0{line_number}".encode()
                    ).hexdigest()
                    findings.append(
                        PluginFinding(
                            rule="TODO001",
                            message="A configured fixture marker is present.",
                            baseline_key=f"todo:{entity}",
                            location=PluginLocation(path, line_number, 1),
                        )
                    )
        return tuple(findings)


scanner = SampleScanner()


class CrashScanner:
    api_version = 1
    plugin_id = "sample.crash"
    rules = (
        PluginRule(
            code="CRASH001",
            default_severity=Severity.ERROR,
            description="A scanner used to verify exception redaction.",
        ),
    )

    def scan(self, repository, config):
        del repository, config
        raise RuntimeError("PRIVATE_FIXTURE_EXCEPTION_VALUE")


crash_scanner = CrashScanner()
